--[[ AETHER TINY SKIES V2 // ENEMY AIRCRAFT EDITION
  Reversible encoded release (not encryption).
  Readable source available in Aether_AirCombat_V2_Source.lua.
  Strict enemy pilot/team linking. Unidentified aircraft excluded.
]]
return (function()
    local data=table.concat({
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
    })
    local bytes={}
    local n=0
    for i=1,#data,2 do
        n=n+1
        bytes[n]=string.char((tonumber(data:sub(i,i+1),16)-47-((n*17)%241))%256)
    end
    local main,err=(loadstring or load)(table.concat(bytes))
    if not main then error("AETHER V2 source decode failed: "..tostring(err)) end
    return main()
end)()
